import {dualTime} from './publishing-policy.js';
const $=id=>document.getElementById(id),node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e};
async function call(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const d=await r.json();if(!r.ok)throw Error(d.error??'队列读取失败');return d}
$('regional-refresh').onclick=async()=>{const button=$('regional-refresh');button.disabled=true;$('regional-message').textContent='读取中…';try{const d=await call('/api/regional');$('regional-rows').replaceChildren(...d.rows.map(r=>{const a=node('article','');a.className='history-card';a.append(node('h3','Português · '+r.state),node('p',dualTime(r.due_at)),node('pre',r.caption));if(['needs_review','review_due'].includes(r.state)){const edit=node('button','载入复核／更新图文');edit.onclick=async()=>{try{const v=await call('/api/regional/load',{id:r.id});$('tab-create').click();window.dispatchEvent(new CustomEvent('regional-review',{detail:v}))}catch(e){$('regional-message').textContent=e.message}};const cancel=node('button','取消此稿');cancel.onclick=async()=>{cancel.disabled=true;try{await call('/api/regional/cancel',{id:r.id});button.click()}catch(e){$('regional-message').textContent=e.message;cancel.disabled=false}};a.append(edit,cancel)}return a}));$('regional-message').textContent=d.rows.length?'仅确认并放行后才会发布，待审稿不会自动发布。':'暂无巴西待审稿'}catch(e){$('regional-message').textContent=e.message}finally{button.disabled=false}};
